head.script:
scwin.trigger1_onclick = function(e) {
    gv.advancedExcelUpload({
        "useMaxByteLength": true
    });
};
scwin.trigger2_onclick = function(e) {
    tb1.setValue(WebSquare.xml.serialize(dataList1.getAllXML()).replaceAll("><", ">\n<"));
    tb2.setValue(WebSquare.xml.serialize(gv.getAllDisplayXML()).replaceAll("><", ">\n<"));
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.common = {};
    common.maskTin = function(tin) {
        try {
            if (tin.length <= 0) return tin;
            window.str = tin.replace(/\-/ig, "");
            if (str.length === 12 || str.length === 9) {
                if (str.replace(/^[P]|[\d]|[\-]/ig, "").length > 0) {
                    //alert("test");
                    return tin;
                }
                return str.replace(/(\w{9})(\d)/g, "$1-$2");
            }
            return tin
        } catch (e) {
            $w.log("Error ::: common.maskTin = " + e.message);
            return tin;
        }
    };
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
